TLM.f("Sancti/08-07o",{"officium":"S. Donati Episcopi et Martyris","rule":["vide C2;","Gloria"],"fallback":"Commune/C2","from":{"GradualeP":"Commune/C2","Tractus":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Dan 3:84; 3:87"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."},{"k":"ref","la":"Dan 3:57"},{"k":"text","la":"Benedícite, ómnia ópera Dómini, Dómino: laudáte et superexaltáte eum in sǽcula."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."}],"Oratio":[{"k":"text","la":"Deus, tuórum glória sacerdótum: præsta, quǽsumus, ut sancti Martyris tui et Epíscopi Donáti, cujus festa gérimus, sentiámus auxílium."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Jacóbi Apóstoli"},{"k":"ref","la":"Jac 1:2-12"},{"k":"text","la":"Caríssimi: Omne gáudium existimáte, cum in tentatiónes várias incidéritis: sciéntes, quod probátio fídei vestræ patiéntiam operátur. Patiéntia autem opus perféctum habet: ut sitis perfécti et intégri in nullo deficiéntes. Si quis autem vestrum índiget sapiéntia, póstulet a Deo, qui dat ómnibus affluénter, et non impróperat: et dábitur ei. Póstulet autem in fide nihil hæsitans: qui enim hæsitat, símilis est flúctui maris, qui a vento movétur et circumfértur. Non ergo æstimet homo ille, quod accípiat áliquid a Dómino. Vir duplex ánimo incónstans est in ómnibus viis suis. Glorietur autem frater húmilis in exaltatióne sua: dives autem in humilitáte sua, quóniam sicut flos fæni tránsibit: exórtus est enim sol cum ardóre et arefécit foenum, et flos ejus décidit et decor vultus ejus depériit: ita et dives in itinéribus suis marcéscet. Beátus vir, qui suffert tentatiónem: quóniam, cum probatus fúerit, accípiet corónam vitæ, quam repromísit Deus diligéntibus se."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Justus non conturbábitur, quia Dóminus firmat manum ejus. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum"},{"k":"ref","la":"Marc 13:33-37"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vidéte, vigiláte et oráte: néscitis enim, quando tempus sit. Sicut homo, qui péregre proféctus ráliquit domum suam, et dedit servis suis potestátem cujúsque óperis, et janitóri præcépit, ut vígilet. Vigiláte ergo - néscitis enim, quando dóminus domus véniat: sero, an média nocte, an galli cantu, an mane - ne, cum vénerit repénte, invéniat vos dormiéntes. Quod autem vobis dico, ómnibus dico: Vigiláte."}],"Offertorium":[{"k":"ref","la":"Ps 88:21-22"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum."}],"Secreta":[{"k":"text","la":"Præsta, quǽsumus, Dómine: ut sancti Martyris tu iet Episcopi Donati intercessióne, quem ad laudem nóminis tui dicátis munéribus honorámus, piæ nobis fructus devotiónis accréscat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Omnípotens et miséricors Deus, qui nos sacramentórum tuórum et partícipes éfficis et minístros: præsta, quǽsumus; ut, intercedénte beáto Donáto Mártyre tuo atque Pontífice, ejúsdem proficiámus et fídei consórtio et digno servítio."},{"k":"macro","name":"Per Dominum"}]},"hr":{"3901d03f3f7a2bcd":{"t":"<i>Pomolimo se</i>.\nBože, slavo svojih svećenika, podaj, molimo, da osjećamo pomoć svetoga tvoga mučenika i biskupa Donata kojega svetkovinu slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"656b64ee8dcc8add":{"t":"Daj, molimo. Gospodine, da nam po zagovoru svetog mučenika i biskupa Donata, kojega častimo darovima prikazanim na slavu tvoga imena, poraste plod pobožne odanosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"75b981ffeee1b18c":{"t":"<i>Pomolimo se</i>.\nSvemogući i milosrdni Bože, koji nas činiš i sudionicima i službenicima svojih otajstava, podaj, molimo, do po zagovoru blaženog Donata tvoga mučenika i biskupa napredujemo po sjedinjenju s njim u vjeri i služimo ti dostojno poput, njega.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
